-- Synthetic Trans Memo v8 export: same structure as the real format, made-up data only.
PRAGMA user_version = 8;
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY, identity_hash TEXT);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, molecule TEXT, unit TEXT, dosePerIntake REAL, capacity REAL, expirationDays INTEGER, intakeInterval INTEGER, soonAlertDelay INTEGER, lateAlertDelay INTEGER DEFAULT 2, handleSide INTEGER, inUse INTEGER, notifications INTEGER);
CREATE TABLE product_intake_time (id INTEGER PRIMARY KEY AUTOINCREMENT, productId INTEGER, intakeTime TEXT);
CREATE TABLE intakes (id INTEGER PRIMARY KEY AUTOINCREMENT, productId INTEGER, scheduledAt TEXT, takenAt TEXT, plannedDose REAL, realDose REAL, plannedSide TEXT, realSide TEXT, state TEXT DEFAULT 'PENDING');
CREATE TABLE containers (id INTEGER PRIMARY KEY AUTOINCREMENT, productId INTEGER, usedCapacity REAL, openDate TEXT, state TEXT);
CREATE TABLE wellbeing_types (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, defaultType TEXT, enabled INTEGER);
CREATE TABLE wellbeing (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT, typeId INTEGER, value INTEGER);
CREATE TABLE notes (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT, text TEXT);
CREATE TABLE medical_appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT, scheduledAt TEXT, location TEXT, doctorName TEXT, notes TEXT, reminderMinutesBefore INTEGER);

-- on time, late by delta, fractional seconds, DST gap (2026-03-29 02:30 Paris) and overlap (2026-10-25 02:30)
